-- ============================================================================
-- MIGRATION 092: Régua de parcelas unificada e catálogo de templates
-- ============================================================================
-- Regras (worker/admin-notificacoes.ts + worker/notificacao-templates-padrao.ts):
--   * uma notificação por cliente por rodada, com todas as parcelas em aberto;
--   * titulo/corpo para 1 parcela, titulo_multiplas/corpo_multiplas para 2+;
--   * atraso: um texto por dia de 1 a 30; 31 = texto único para 31+ dias;
--   * D-2, D-1 e D0 antes do vencimento.
-- Os textos abaixo são gerados de worker/notificacao-templates-padrao.ts.
--
-- Não destrutiva: os templates de parcela anteriores (inclusive duplicados)
-- ficam copiados em notificacao_templates_backup_092.
-- Rollback: apagar as linhas parcela_vencer/parcela_atrasada, reinserir a
-- partir do backup e remover o índice ux_notificacao_templates_regua.

create table if not exists notificacao_templates_backup_092 as
  select * from notificacao_templates where tipo in ('parcela_vencer', 'parcela_atrasada');
alter table notificacao_templates_backup_092 enable row level security;

alter table notificacao_templates add column if not exists titulo_multiplas text;
alter table notificacao_templates add column if not exists corpo_multiplas text;

delete from notificacao_templates where tipo in ('parcela_vencer', 'parcela_atrasada');

create unique index if not exists ux_notificacao_templates_regua
  on notificacao_templates (tipo, dias_referencia)
  where tipo in ('parcela_vencer', 'parcela_atrasada');


on conflict (chave) do nothing;
